import React, { useEffect, useState } from "react";
import Modal from "./Modal";
import useOrderStore from "../stores/orderStore";
import useAuthStore from "../stores/authStore";
import { formatPrice } from "../utils/PriceFormat";
import VidaLogo from "../assets/images/vida-logo.png";
import "./OrderModal.css";

const VIDA_LOGO_B64 = "data:image/png;base64,";

/* ─── Label maps ─────────────────────────────────────── */
const tractorTypeLabels = {
  ROMANIAN_UNIVERSAL: "رومانی یونیورسال",
  FERGUSON: "فرگوسن",
  JOHN_DEERE: "جان دیر",
  NEW_HOLLAND: "نیوهلند",
  CASE: "کیس",
  OTHER: "سایر",
};
const combineUsageLabels = {
  WHEAT: "گندم",
  RICE: "برنج",
  MULTIPURPOSE: "چندمنظوره",
};
const chopperTypeLabels = {
  SELF_PROPELLED: "خودکششی",
  PULL_TYPE: "دنباله‌بند",
};
const paymentLabels = { CASH: "نقدی", INSTALLMENT: "اقساط" };
const statusColors = {
  PAID: "paid",
  PENDING: "pending",
  CANCELLED: "cancelled",
  COMPLETED: "completed",
};

/* ─── Helpers ────────────────────────────────────────── */
const toPersian = (n) => {
  if (n == null) return "";
  return n.toString().replace(/\d/g, (d) => "۰۱۲۳۴۵۶۷۸۹"[d]);
};

const getMachineKind = (machinery) => {
  if (!machinery) return "نامشخص";
  if (machinery.tractor) return "تراکتور";
  if (machinery.combine) return "کمباین";
  if (machinery.chopper) return "چاپر";
  return "ماشین";
};

const getMachineDetail = (machinery) => {
  if (!machinery) return "";
  if (machinery.tractor)
    return tractorTypeLabels[machinery.tractor.tractor_type] || machinery.tractor.tractor_type;
  if (machinery.combine)
    return combineUsageLabels[machinery.combine.usage_type] || machinery.combine.usage_type;
  if (machinery.chopper)
    return chopperTypeLabels[machinery.chopper.chopper_type] || machinery.chopper.chopper_type;
  return "";
};

const persianDate = (iso) => {
  if (!iso) return new Date().toLocaleDateString("fa-IR");
  try {
    return new Date(iso).toLocaleDateString("fa-IR");
  } catch {
    return new Date().toLocaleDateString("fa-IR");
  }
};

/* ════════════════════════════════════════════════════════
   buildFactorHTML — standalone A4 document for new-window print
   ════════════════════════════════════════════════════════ */
const buildFactorHTML = (order, user, logoUrl) => {
  const orderUser = order.user || user || {};
  const machinery = order.machinery || {};
  const machineKind = getMachineKind(order.machinery);
  const machineDetail = getMachineDetail(order.machinery);
  const priceAtPurchase =
    order.price_at_purchase != null
      ? formatPrice(order.price_at_purchase)
      : order.product?.price != null
      ? formatPrice(order.product.price)
      : "—";

  return `<!DOCTYPE html>
<html dir="rtl" lang="fa">
<head>
<meta charset="UTF-8"/>
<title>فاکتور شماره ${order.oid || ""}</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  @page{size:A4 portrait;margin:0}
  body{font-family:Tahoma,Arial,sans-serif;font-size:10pt;color:#1a1a1a;direction:rtl;background:#fff}

  .factor{width:210mm;min-height:297mm;padding:14mm 16mm;background:#fff}

  /* ── header ── */
  .fp-header{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:10px;margin-bottom:4px}
  .fp-header-right{display:flex;flex-direction:column;align-items:flex-start;gap:5px}
  .fp-vida-logo{width:56px;height:56px;object-fit:contain}
  .fp-vida-name{font-size:13pt;font-weight:700;color:#1e3a6e;line-height:1.3}
  .fp-vida-sub{font-size:8.5pt;color:#64748b}
  .fp-header-center{text-align:center}
  .fp-doc-title{font-size:17pt;font-weight:800;color:#1e3a6e;letter-spacing:-0.5px;white-space:nowrap}
  .fp-header-left{display:flex;flex-direction:column;align-items:flex-end;gap:4px}
  .fp-meta-row{display:flex;gap:6px;font-size:9.5pt}
  .fp-meta-label{color:#64748b;white-space:nowrap}
  .fp-meta-val{font-weight:700;color:#1a1a1a}

  /* ── divider ── */
  .fp-divider{height:2px;background:linear-gradient(to left,#1e3a6e,#4a7fd4,#1e3a6e);margin:9px 0}

  /* ── section ── */
  .fp-section{margin:10px 0}
  .fp-section-title{font-size:10.5pt;font-weight:700;color:#1e3a6e;border-right:3px solid #1e3a6e;padding-right:8px;margin-bottom:8px}

  /* ── buyer grid ── */
  .fp-info-grid{display:grid;grid-template-columns:1fr 1fr;gap:5px 24px}
  .fp-info-cell{display:flex;gap:5px;font-size:9.5pt;align-items:baseline}
  .fp-info-cell--wide{grid-column:1/-1}
  .fp-info-label{color:#64748b;white-space:nowrap;font-size:9pt}
  .fp-info-val{font-weight:600;color:#1a1a1a}

  /* ── table ── */
  .fp-table{width:100%;border-collapse:collapse;font-size:9.5pt}
  .fp-table th{background:#1e3a6e;color:#fff;padding:7px 9px;text-align:center;font-weight:600;font-size:9pt}
  .fp-table tbody td{padding:7px 9px;border-bottom:1px solid #e2e8f0;text-align:center;vertical-align:middle}
  .fp-table tbody tr:nth-child(even) td{background:#f8fafc}
  .fp-amount{font-weight:700;font-family:Tahoma,monospace;direction:ltr}
  .fp-total-row td{padding:8px 9px;background:#eef2f9!important;font-weight:700;border-top:2px solid #1e3a6e}
  .fp-total-label{text-align:right;color:#1e3a6e;font-size:10pt}
  .fp-total-val{font-size:11pt;color:#1e3a6e}

  /* ── ref ── */
  .fp-ref-row{display:flex;align-items:center;gap:10px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;padding:7px 14px;margin:10px 0;font-size:9.5pt}
  .fp-ref-label{color:#64748b}
  .fp-ref-val{font-weight:700;font-family:Tahoma,monospace;color:#1e3a6e;direction:ltr}

  /* ── notes ── */
  .fp-notes{background:#fafbfc;border:1px dashed #cbd5e1;border-radius:6px;padding:7px 12px;margin:8px 0 12px}
  .fp-notes p{margin:0 0 3px;font-size:8.5pt;color:#555;line-height:1.55}
  .fp-notes p:last-child{margin-bottom:0}

  /* ── signatures ── */
  .fp-signatures{display:grid;grid-template-columns:1fr 1fr;gap:2rem;margin:14px 0 10px}
  .fp-sig-box{display:flex;flex-direction:column;align-items:center;gap:7px}
  .fp-sig-label{font-size:9.5pt;font-weight:600;color:#334155}
  .fp-sig-area{width:100%;height:65px;border:1px dashed #94a3b8;border-radius:4px}

  /* ── footer ── */
  .fp-footer{text-align:center;font-size:8pt;color:#94a3b8;border-top:1px solid #e2e8f0;padding-top:7px;margin-top:10px}
</style>
</head>
<body>
<div class="factor">

  <div class="fp-header">
    <div class="fp-header-right">
      <img src="${logoUrl}" alt="ویدا" class="fp-vida-logo"/>
      <div class="fp-vida-name">شرکت تکاپو گسترش ویدا</div>
      <div class="fp-vida-sub">سامانه هوشمند پایش سوخت ماشین آلات کشاورزی</div>
    </div>
    <div class="fp-header-center">
      <div class="fp-doc-title">فاکتور رسمی</div>
    </div>
    <div class="fp-header-left">
      <div class="fp-meta-row"><span class="fp-meta-label">شماره فاکتور:</span><span class="fp-meta-val">${toPersian(order.oid)}</span></div>
      <div class="fp-meta-row"><span class="fp-meta-label">تاریخ:</span><span class="fp-meta-val">${persianDate(order.createdAt)}</span></div>
      <div class="fp-meta-row"><span class="fp-meta-label">روش پرداخت:</span><span class="fp-meta-val">${paymentLabels[order.payment_method] || order.payment_method || "—"}</span></div>
    </div>
  </div>

  <div class="fp-divider"></div>

  <div class="fp-section">
    <div class="fp-section-title">مشخصات خریدار</div>
    <div class="fp-info-grid">
      <div class="fp-info-cell"><span class="fp-info-label">نام و نام خانوادگی:</span><span class="fp-info-val">${orderUser.name || "—"}</span></div>
      <div class="fp-info-cell"><span class="fp-info-label">کد ملی:</span><span class="fp-info-val">${orderUser.national_code || order.user_id || "—"}</span></div>
      <div class="fp-info-cell"><span class="fp-info-label">شماره تماس:</span><span class="fp-info-val">${orderUser.phone || "—"}</span></div>
      <div class="fp-info-cell"><span class="fp-info-label">استان / شهر:</span><span class="fp-info-val">${orderUser.province || "مرکزی"} / ${orderUser.city || "—"}</span></div>
      <div class="fp-info-cell"><span class="fp-info-label">روستا:</span><span class="fp-info-val">${orderUser.village || "—"}</span></div>
      <div class="fp-info-cell fp-info-cell--wide"><span class="fp-info-label">آدرس:</span><span class="fp-info-val">${orderUser.address || "—"}</span></div>
    </div>
  </div>

  <div class="fp-divider"></div>

  <div class="fp-section">
    <div class="fp-section-title">شرح خدمات</div>
    <table class="fp-table">
      <thead>
        <tr>
          <th>ردیف</th>
          <th>نام محصول / خدمت</th>
          <th>نوع ماشین</th>
          <th>مدل</th>
          <th>سال ساخت</th>
          <th>قیمت محصول (تومان)</th>
          <th>مبلغ پرداختی (تومان)</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td>۱</td>
          <td>${order.product?.name || "—"}</td>
          <td>${machineKind}${machineDetail ? " — " + machineDetail : ""}</td>
          <td>${machinery.model || "—"}</td>
          <td>${toPersian(machinery.manufacture_year) || "—"}</td>
          <td class="fp-amount">${priceAtPurchase}</td>
          <td class="fp-amount">${formatPrice(order.paid)}</td>
        </tr>
      </tbody>
      <tfoot>
        <tr class="fp-total-row">
          <td colspan="6" class="fp-total-label">جمع کل پرداختی</td>
          <td class="fp-amount fp-total-val">${formatPrice(order.paid)}</td>
        </tr>
      </tfoot>
    </table>
  </div>

  <div class="fp-ref-row">
    <span class="fp-ref-label">کد پیگیری تراکنش:</span>
    <span class="fp-ref-val" dir="ltr">${order.ref_id || "—"}</span>
  </div>

  <div class="fp-divider"></div>

  <div class="fp-notes">
    <p>این فاکتور سند معتبر خرید خدمات ماشین‌آلات کشاورزی می‌باشد.</p>
    <p>در صورت نیاز به پیگیری، لطفاً کد فاکتور و کد پیگیری تراکنش را به همراه داشته باشید.</p>
  </div>

  <div class="fp-signatures">
    <div class="fp-sig-box"><div class="fp-sig-label">مهر و امضاء فروشنده</div><div class="fp-sig-area"></div></div>
    <div class="fp-sig-box"><div class="fp-sig-label">مهر و امضاء خریدار</div><div class="fp-sig-area"></div></div>
  </div>

  <div class="fp-footer">شرکت تکاپو گسترش ویدا — سامانه مدیریت ماشین‌آلات کشاورزی</div>
</div>
<script>
  var img = document.querySelector('.fp-vida-logo');
  function doPrint() { window.focus(); window.print(); }
  if (img && !img.complete) { img.onload = doPrint; img.onerror = doPrint; }
  else { doPrint(); }
</script>
</body>
</html>`;
};

/* ════════════════════════════════════════════════════════
   FactorView — A4 invoice overlay (preview only)
   ════════════════════════════════════════════════════════ */
const FactorView = ({ order, user, onBack }) => {
  const machinery = order.machinery || {};
  const machineKind = getMachineKind(order.machinery);
  const machineDetail = getMachineDetail(order.machinery);
  const orderUser = order.user || user || {};

  return (
    <div className="factor-overlay">
      {/* Toolbar — hidden on print */}
      <div className="factor-toolbar no-print">
        <button className="factor-back-btn" onClick={onBack}>
          <i className="bi bi-arrow-right"></i> بازگشت
        </button>
        <button
          className="factor-print-btn"
          onClick={() => {
            // VIDA_LOGO_B64 is an inlined base64 data URL — always available,
            // no fetch/canvas needed, works perfectly in any iframe or new window.
            const iframe = document.createElement("iframe");
            iframe.style.cssText =
              "position:fixed;top:0;left:0;width:0;height:0;border:none;visibility:hidden";
            document.body.appendChild(iframe);

            const doc =
              iframe.contentDocument || iframe.contentWindow.document;
            doc.open();
            doc.write(buildFactorHTML(order, user, VIDA_LOGO_B64));
            doc.close();

            setTimeout(() => {
              iframe.contentWindow.focus();
              iframe.contentWindow.print();
              setTimeout(() => {
                if (iframe.parentNode) iframe.parentNode.removeChild(iframe);
              }, 1500);
            }, 100);
          }}
        >
          <i className="bi bi-printer"></i> چاپ / دانلود PDF
        </button>
      </div>

      {/* A4 document */}
      <div className="factor-page factor-print-area">

        {/* ── Header ── */}
        <div className="fp-header">
          {/* Right: company identity */}
          <div className="fp-header-right">
            <img src={VIDA_LOGO_B64} alt="لوگو ویدا" className="fp-vida-logo" />
            <div className="fp-vida-name">شرکت تکاپو گسترش ویدا</div>
            <div className="fp-vida-sub">سامانه هوشمند پایش سوخت ماشین آلات کشاورزی</div>
          </div>

          {/* Center: title */}
          <div className="fp-header-center">
            <div className="fp-doc-title">فاکتور رسمی</div>
          </div>

          {/* Left: invoice meta */}
          <div className="fp-header-left">
            <div className="fp-meta-row">
              <span className="fp-meta-label">شماره فاکتور:</span>
              <span className="fp-meta-val">{toPersian(order.oid)}</span>
            </div>
            <div className="fp-meta-row">
              <span className="fp-meta-label">تاریخ:</span>
              <span className="fp-meta-val">{persianDate(order.createdAt)}</span>
            </div>
            <div className="fp-meta-row">
              <span className="fp-meta-label">روش پرداخت:</span>
              <span className="fp-meta-val">{paymentLabels[order.payment_method] || order.payment_method}</span>
            </div>
          </div>
        </div>

        <div className="fp-divider"></div>

        {/* ── Buyer info ── */}
        <div className="fp-section">
          <div className="fp-section-title">مشخصات خریدار</div>
          <div className="fp-info-grid">
            <div className="fp-info-cell">
              <span className="fp-info-label">نام و نام خانوادگی:</span>
              <span className="fp-info-val">{orderUser.name || "—"}</span>
            </div>
            <div className="fp-info-cell">
              <span className="fp-info-label">کد ملی:</span>
              <span className="fp-info-val">{orderUser.national_code || order.user_id || "—"}</span>
            </div>
            <div className="fp-info-cell">
              <span className="fp-info-label">شماره تماس:</span>
              <span className="fp-info-val">{orderUser.phone || "—"}</span>
            </div>
            <div className="fp-info-cell">
              <span className="fp-info-label">استان / شهر:</span>
              <span className="fp-info-val">
                {orderUser.province || "مرکزی"} / {orderUser.city || "—"}
              </span>
            </div>
            <div className="fp-info-cell">
              <span className="fp-info-label">روستا:</span>
              <span className="fp-info-val">{orderUser.village || "—"}</span>
            </div>
            <div className="fp-info-cell fp-info-cell--wide">
              <span className="fp-info-label">آدرس:</span>
              <span className="fp-info-val">{orderUser.address || "—"}</span>
            </div>
          </div>
        </div>

        <div className="fp-divider"></div>

        {/* ── Order details table ── */}
        <div className="fp-section">
          <div className="fp-section-title">شرح خدمات</div>
          <table className="fp-table">
            <thead>
              <tr>
                <th>ردیف</th>
                <th>نام محصول / خدمت</th>
                <th>نوع ماشین</th>
                <th>مدل</th>
                <th>سال ساخت</th>
                <th>قیمت محصول (تومان)</th>
                <th>مبلغ پرداختی (تومان)</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>۱</td>
                <td>{order.product?.name || "—"}</td>
                <td>
                  {machineKind}
                  {machineDetail ? ` — ${machineDetail}` : ""}
                </td>
                <td>{machinery.model || "—"}</td>
                <td>{toPersian(machinery.manufacture_year) || "—"}</td>
                <td className="fp-amount">
                  {order.price_at_purchase != null
                    ? formatPrice(order.price_at_purchase)
                    : order.product?.price != null
                    ? formatPrice(order.product.price)
                    : "—"}
                </td>
                <td className="fp-amount">{formatPrice(order.paid)}</td>
              </tr>
            </tbody>
            <tfoot>
              <tr className="fp-total-row">
                <td colSpan={6} className="fp-total-label">جمع کل پرداختی</td>
                <td className="fp-amount fp-total-val">{formatPrice(order.paid)}</td>
              </tr>
            </tfoot>
          </table>
        </div>

        {/* ── Reference / tracking ── */}
        <div className="fp-ref-row">
          <span className="fp-ref-label">کد پیگیری تراکنش:</span>
          <span className="fp-ref-val" dir="ltr">{order.ref_id || "—"}</span>
        </div>

        <div className="fp-divider"></div>

        {/* ── Notes ── */}
        <div className="fp-notes">
          <p>این فاکتور سند معتبر خرید خدمات ماشین‌آلات کشاورزی می‌باشد.</p>
          <p>در صورت نیاز به پیگیری، لطفاً کد فاکتور و کد پیگیری تراکنش را به همراه داشته باشید.</p>
        </div>

        {/* ── Signatures ── */}
        <div className="fp-signatures">
          <div className="fp-sig-box">
            <div className="fp-sig-label">مهر و امضاء فروشنده</div>
            <div className="fp-sig-area"></div>
          </div>
          <div className="fp-sig-box">
            <div className="fp-sig-label">مهر و امضاء خریدار</div>
            <div className="fp-sig-area"></div>
          </div>
        </div>

        {/* ── Footer ── */}
        <div className="fp-footer">
          <span>شرکت تکاپو گسترش ویدا — سامانه مدیریت ماشین‌آلات کشاورزی</span>
        </div>
      </div>
    </div>
  );
};

/* ════════════════════════════════════════════════════════
   Order card
   ════════════════════════════════════════════════════════ */
const OrderCard = ({ order, onPrintFactor }) => {
  const machinery = order.machinery || {};
  const machineKind = getMachineKind(order.machinery);
  const detail = getMachineDetail(order.machinery);

  return (
    <div className={`order-card order-card--${statusColors[order.status] || "default"}`}>
      <div className="oc-top">
        <span className={`oc-status oc-status--${statusColors[order.status] || "default"}`}>
          {order.statusText || order.status}
        </span>
        <span className="oc-date">{persianDate(order.createdAt)}</span>
      </div>

      <div className="oc-product">{order.product?.name || "—"}</div>

      <div className="oc-machine">
        <span className="oc-machine-kind">{machineKind}</span>
        {machinery.model && <span className="oc-machine-sep">·</span>}
        {machinery.model && <span className="oc-machine-model">{machinery.model}</span>}
        {detail && <span className="oc-machine-sep">·</span>}
        {detail && <span className="oc-machine-detail">{detail}</span>}
        {machinery.manufacture_year && (
          <>
            <span className="oc-machine-sep">·</span>
            <span className="oc-machine-year">ساخت {toPersian(machinery.manufacture_year)}</span>
          </>
        )}
      </div>

      <div className="oc-bottom">
        <div className="oc-payment">
          <span className="oc-payment-method">
            {paymentLabels[order.payment_method] || order.payment_method}
          </span>
          <span className="oc-payment-amount">{formatPrice(order.paid)} تومان</span>
        </div>
        <button className="oc-factor-btn" onClick={() => onPrintFactor(order)}>
          <i className="bi bi-printer"></i>
          چاپ فاکتور
        </button>
      </div>

      {order.ref_id && (
        <div className="oc-ref">کد پیگیری: <span dir="ltr">{order.ref_id}</span></div>
      )}
    </div>
  );
};

/* ════════════════════════════════════════════════════════
   Main modal
   ════════════════════════════════════════════════════════ */
const OrdersModal = ({ isOpen, onClose }) => {
  const { orders, fetchOrders, isLoading, error, clearError } = useOrderStore();
  const { user } = useAuthStore();
  const [factorOrder, setFactorOrder] = useState(null);

  useEffect(() => {
    if (isOpen) fetchOrders();
    else { clearError(); setFactorOrder(null); }
  }, [isOpen, fetchOrders, clearError]);

  if (factorOrder) {
    return (
      <FactorView
        order={factorOrder}
        user={user}
        onBack={() => setFactorOrder(null)}
      />
    );
  }

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="سفارش‌های من" className="orders-modal">
      <div className="orders-modal-body">

        {isLoading && (
          <div className="om-loading">
            <div className="om-spinner"></div>
            <p>در حال دریافت سفارش‌ها...</p>
          </div>
        )}

        {error && !isLoading && (
          <div className="om-error">
            <i className="bi bi-exclamation-circle"></i>
            <p>{error}</p>
            <button onClick={fetchOrders} className="om-retry-btn">تلاش مجدد</button>
          </div>
        )}

        {!isLoading && !error && orders.length === 0 && (
          <div className="om-empty">
            <i className="bi bi-bag-x"></i>
            <p>هنوز سفارشی ثبت نکرده‌اید.</p>
          </div>
        )}

        {!isLoading && !error && orders.length > 0 && (
          <div className="om-cards">
            {orders.map((order) => (
              <OrderCard
                key={order.oid}
                order={order}
                onPrintFactor={setFactorOrder}
              />
            ))}
          </div>
        )}

        <div className="om-footer">
          <button className="om-close-btn" onClick={onClose}>بستن</button>
        </div>
      </div>
    </Modal>
  );
};

export default OrdersModal;
